'use client'

import * as React from 'react'
import { DocsScrollbar } from '@/components/spaceui/docs-scrollbar'
import { Badge } from '@/components/ui/badge'

const SECTIONS = [
  { title: 'Installation', badge: '01' },
  { title: 'Usage', badge: '02' },
  { title: 'Theming', badge: '03' },
  { title: 'API reference', badge: '04' },
  { title: 'Examples', badge: '05' },
]

export default function DocsScrollbarDemo() {
  const scrollRef = React.useRef<HTMLDivElement>(null)

  return (
    <div className="relative h-[420px] w-full overflow-hidden rounded-[0.875rem] bg-muted">
      <div ref={scrollRef} className="h-full overflow-y-auto p-5 pb-28">
        {SECTIONS.map((section) => (
          <section key={section.title} data-page-section className="mb-8 space-y-3">
            <h2 className="flex items-center gap-2 text-base font-semibold text-foreground">
              {section.title}
              <Badge variant="secondary">{section.badge}</Badge>
            </h2>
            <div className="h-40 rounded-2xl bg-background" />
          </section>
        ))}
      </div>
      <DocsScrollbar containerRef={scrollRef} />
    </div>
  )
}
